-- M7.2: disposable, rollback-only direct-role bypass and privacy checks.
begin;
-- The fresh legacy fixture grants auth usage; reproduce the hosted restricted role here.
revoke usage on schema auth from castly_api;
create schema enforcement_test;
create function enforcement_test.ok(value boolean,label text) returns void language plpgsql security invoker as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function enforcement_test.denied(statement text,label text) returns void language plpgsql security invoker as $$begin begin execute statement;exception when insufficient_privilege then raise notice 'PASS %',label;return;end;raise exception 'FAIL % unexpectedly permitted',label;end$$;
grant usage on schema enforcement_test to castly_api,authenticated,anon,castly_engagement_worker;
grant execute on all functions in schema enforcement_test to castly_api,authenticated,anon,castly_engagement_worker;
select enforcement_test.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='enforcement_private' and p.prosecdef),'enforcement uses no SECURITY DEFINER');
select enforcement_test.ok((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='enforcement_private' and c.relkind='r'),'all enforcement tables have RLS');
select enforcement_test.ok(not has_schema_privilege('castly_api','auth','USAGE'),'auth schema fallback boundary preserved');
select enforcement_test.ok(not has_table_privilege('castly_api','public.bookings','UPDATE'),'no table-wide booking UPDATE');
insert into auth.users(id) values('73000000-0000-0000-0000-000000000001'),('73000000-0000-0000-0000-000000000002'),('73000000-0000-0000-0000-000000000003'),('73000000-0000-0000-0000-000000000004');
update public.users set primary_role='talent' where id='73000000-0000-0000-0000-000000000002';
update public.users set primary_role='client' where id='73000000-0000-0000-0000-000000000003';
insert into public.talent_profiles(id,display_name,category_id,city,day_rate,bio,skills,published) values('73000000-0000-0000-0000-000000000002','Local restricted talent','actors','Pune',1000,'Fixture',array['acting'],true);
insert into public.bookings(client_id,talent_id,project_type,proposed_date,location,requirements,indicative_budget) values('73000000-0000-0000-0000-000000000003','73000000-0000-0000-0000-000000000002','Local obligation',current_date+2,'Pune','Fixture existing booking',1000);
set local castly.admin_bootstrap_reviewed='M7.1-owner-approved';
insert into admin_private.principals(user_id,roles,state) values('73000000-0000-0000-0000-000000000001',array['SUPER_ADMIN'],'active');
select set_config('request.jwt.claim.sub','73000000-0000-0000-0000-000000000001',true),set_config('request.admin.aal2','true',true),set_config('request.admin.mfa_at',now()::text,true),set_config('request.admin.auth_session','73000000-0000-0000-0000-000000000099',true);
set local role castly_api;
insert into admin_private.sessions(user_id,auth_session_id,principal_version,ip_fingerprint,agent_family) values(private.request_user_id(),'73000000-0000-0000-0000-000000000099',1,'fixture','other') returning id as session_id \gset
select set_config('request.admin.session',:'session_id',true);
insert into enforcement_private.commands(request_key,operation,user_id,payload) values('73000000-0000-0000-0000-000000000090','ENFORCE','73000000-0000-0000-0000-000000000002','{"version":0,"state":"TEMPORARILY_SUSPENDED","duration_hours":1,"reason_code":"ACCOUNT_COMPROMISE","explanation":"Protective hold, security recovery remains available.","evidence_ref":"internal:case-reference","notes":"NEVER EXPOSE THESE NOTES"}');
select enforcement_test.ok((select version=1 from enforcement_private.accounts where user_id='73000000-0000-0000-0000-000000000002'),'restricted command succeeds without administrator DB credentials');
with changed as(update enforcement_private.accounts set state='ACTIVE' returning user_id) select enforcement_test.ok((select count(*)=0 from changed),'direct account state overwrite affects zero rows');
select enforcement_test.denied($q$insert into enforcement_private.capabilities values(gen_random_uuid(),'{}',null,false,'-infinity')$q$,'direct capability forgery denied');
select enforcement_test.denied($q$insert into enforcement_private.events(user_id,actor_id,operation,public_data) values(private.request_user_id(),private.request_user_id(),'forged','{}')$q$,'event forgery denied');
select enforcement_test.denied($q$delete from enforcement_private.decisions$q$,'immutable decisions cannot be deleted');
select enforcement_test.denied($q$update enforcement_private.notes set notes='forged'$q$,'immutable notes cannot be rewritten');
select set_config('request.admin.session','',true),set_config('request.jwt.claim.sub','73000000-0000-0000-0000-000000000002',true);
select enforcement_test.ok((select count(*)=1 from public.bookings where project_type='Local obligation'),'suspended talent retains existing booking obligation');
select enforcement_test.ok((select count(*)=0 from enforcement_private.notes),'account owner cannot read confidential investigation notes');
select enforcement_test.ok((select count(*)=1 from enforcement_private.notices),'account gets durable transactional notice');
select enforcement_test.ok(not private.discovery_talent_visible(private.request_user_id()),'owner cannot use discovery helpers to expose a restricted profile');
select enforcement_test.ok(not enforcement_private.allowed(private.request_user_id(),'subscription_purchase'),'new purchases denied without revoking existing entitlements');
select enforcement_test.denied($q$update public.talent_profiles set published=false where id=private.request_user_id()$q$,'business API profile mutation denied');
select set_config('request.jwt.claim.sub','73000000-0000-0000-0000-000000000003',true);
select enforcement_test.ok((select count(*)=1 from public.bookings where project_type='Local obligation'),'counterparty retains booking access');
select enforcement_test.ok((select count(*)=0 from public.talent_profiles where id='73000000-0000-0000-0000-000000000002'),'restricted talent absent from counterparty discovery');
select enforcement_test.ok((select count(*)=0 from enforcement_private.accounts),'unrelated private case not visible');
select enforcement_test.denied($q$insert into public.bookings(client_id,talent_id,project_type,proposed_date,location,requirements,indicative_budget) values(private.request_user_id(),'73000000-0000-0000-0000-000000000002','Bypass',current_date+2,'Pune','No bypass',1000)$q$,'restricted talent cannot receive new bookings');
reset role;
select set_config('request.jwt.claim.sub','73000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select enforcement_test.denied($q$select * from enforcement_private.accounts$q$,'direct Supabase cannot read cases');
select enforcement_test.denied($q$insert into enforcement_private.commands(request_key,operation,user_id,payload) values(gen_random_uuid(),'REINSTATE',enforcement_private.actor(),'{}')$q$,'direct Supabase cannot write administrative commands');
select enforcement_test.denied($q$update public.talent_profiles set published=true where id=enforcement_private.actor()$q$,'direct Supabase profile update cannot bypass restrictions');
select enforcement_test.denied($q$insert into storage.objects(bucket_id,name) values('portfolio',enforcement_private.actor()::text||'/new.png')$q$,'direct Storage portfolio upload denied');
reset role;
set local role anon;
select enforcement_test.ok((select count(*)=0 from public.talent_profiles where id='73000000-0000-0000-0000-000000000002'),'anonymous discovery hides restricted talent');
select enforcement_test.denied($q$select denied from enforcement_private.capabilities$q$,'anonymous role cannot read restriction metadata');
reset role;
set local role castly_engagement_worker;
select enforcement_test.ok(not enforcement_private.not_suspended('73000000-0000-0000-0000-000000000002'),'worker eligibility excludes suspended recipient');
select enforcement_test.denied($q$select * from enforcement_private.notes$q$,'delivery worker cannot read confidential notes');
reset role;
rollback;
